+			const zipSelector = $body.find("#field-billing_zip_code").length > 0
+				? "#field-billing_zip_code"
+				: '[name="billing_address[billing_zip_code]"]';
+			if ($body.find(zipSelector).length > 0) {
+				cy.get(zipSelector).clear().type("94105");
+			}
+		});
```
