+		// Redirect to remove query parameters
+		wp_safe_redirect(
+			add_query_arg(
+				[
+					'page'             => 'wp-ultimo-settings',
+					'tab'              => 'payment-gateways',
+					'paypal_connected' => '1',
+				],
+				network_admin_url('admin.php')
+			)
+		);
+		exit;
+	}
