+
+			$found = false;
+
+			foreach ($constants as $const) {
+				if (defined($const) && constant($const)) {
+					$found = true;
+					break;
+				}
+			}
+
+			if ( ! $found) {
+				$missing = array_merge($missing, $constants);
+			}
+		}
+
+		return $missing;
+	}
