+		// Cloudflare doesn't support proxied for certain record types
+		if (in_array($data['type'], ['MX', 'TXT'], true)) {
+			unset($data['proxied']);
+		}
+
+		$response = $this->cloudflare_api_call(
+			"client/v4/zones/{$zone_id}/dns_records",
+			'POST',
+			$data
+		);
+
+		if (is_wp_error($response)) {
+			wu_log_add(
