+	/**
+	 * The cipher method used for encryption.
+	 *
+	 * @var string
+	 */
+	const CIPHER_METHOD = 'aes-256-cbc';
+
+	/**
+	 * Prefix for encrypted values to identify them.
+	 *
+	 * @var string
