-		// Delete the WordPress blog if it exists.
-		if ($blog_id) {
-			wpmu_delete_blog($blog_id, true);
-		}
-
-		// Delete the WP Ultimo site record.
-		$result = $site->delete();
+		// Delete the site once, then stop if the deletion did not complete.
+		$result = $site->delete();
