+		);
+
+		if (is_wp_error($result)) {
+			return [
+				'success' => false,
+				'message' => $result->get_error_message(),
+			];
+		}
+
+		$records = $this->extract_dns_records($result, $domain);
+
+		return [
+			'success' => true,
+			'records' => $records,
+		];
+	}
+
+	/**
