+		$from_email = apply_filters('wu_ses_from_email', $from_email, $from_name, $domain);
+		$from_name  = apply_filters('wu_ses_from_name', $from_name, $from_email, $domain);
+
+		if ($from_name) {
+			return sprintf('%s <%s>', $from_name, $from_email);
+		}
