+class Amazon_SES_Transactional_Email extends Base_Capability_Module implements Transactional_Email_Capability {
+
+	/**
+	 * {@inheritdoc}
+	 */
+	public function get_capability_id(): string {
+
+		return 'transactional-email';
+	}
+
+	/**
+	 * {@inheritdoc}
